"use client";

import { useEffect, useId, useRef, useState } from "react";

import {
  ChevronDownIcon,
  PlusIcon,
  RefreshIcon,
  SparklesIcon,
} from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";

import { BlockFrame } from "../parts/block-frame";
import { CiteButton } from "./ai-answer/cite-button";
import {
  ANSWERS,
  type AnswerId,
  QUESTION,
  REGENERATE,
  RELATED,
  SOURCES,
} from "./ai-answer/data";
import { SourcesRow } from "./ai-answer/sources-row";
import { ShareIcon } from "./icons";
import { answerSize, answerText } from "./shared/answer";
import { PromptField } from "./shared/prompt-field";
import { type Rating, ReplyActions } from "./shared/reply-actions";
import { StreamAnswer } from "./shared/stream-answer";
import { ThoughtRow } from "./shared/thought-row";
import { useWordStream } from "./shared/use-word-stream";

interface Version {
  answer: AnswerId;
  rating: Rating;
}

const REGENERATE_TO = {
  shorter: "shorter",
  detail: "main",
  simple: "simple",
} satisfies Record<(typeof REGENERATE)[number]["id"], AnswerId>;

/**
 * One answer laid out like a short article: the question as its title, a
 * thinking row, the sources it read, then prose with numbered citations,
 * headed sections, a table and code. Citations light the sentence they
 * support. Copy, regenerate, rate, share and page through versions.
 */
export function AiAnswer({ className }: { className?: string }) {
  const titleId = useId();
  const [question, setQuestion] = useState(QUESTION);
  const [versions, setVersions] = useState<Version[]>([
    { answer: "main", rating: null },
  ]);
  const [active, setActive] = useState(0);
  const [lit, setLit] = useState<number | null>(null);
  const [sourcesOpen, setSourcesOpen] = useState(false);
  const [shared, setShared] = useState(false);
  const stream = useWordStream({ delay: 1000 });
  const shareTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const version = versions[active]!;
  const answer = ANSWERS[version.answer];
  const [liveAt, setLiveAt] = useState(0);
  const isLive = stream.busy && liveAt === active;

  const play = (answerId: AnswerId, index: number) => {
    setLiveAt(index);
    stream.start(answerSize(ANSWERS[answerId].parts));
  };

  // The opening answer streams in once when the block appears.
  const { start } = stream;
  useEffect(() => {
    start(answerSize(ANSWERS.main.parts));
  }, [start]);

  useEffect(
    () => () => {
      if (shareTimer.current) clearTimeout(shareTimer.current);
    },
    [],
  );

  const ask = (nextQuestion: string, answerId: AnswerId) => {
    setQuestion(nextQuestion);
    setVersions([{ answer: answerId, rating: null }]);
    setActive(0);
    setSourcesOpen(false);
    play(answerId, 0);
  };

  const regenerate = (answerId: AnswerId) => {
    const index = versions.length;
    setVersions((list) => [...list, { answer: answerId, rating: null }]);
    setActive(index);
    play(answerId, index);
  };

  const share = () => {
    void navigator.clipboard
      ?.writeText("https://fernhill.app/answers/late-cancellations")
      .catch(() => undefined);
    setShared(true);
    if (shareTimer.current) clearTimeout(shareTimer.current);
    shareTimer.current = setTimeout(() => setShared(false), 2000);
  };

  const thinking = isLive && stream.status === "waiting";
  const shown =
    isLive || (stream.status === "stopped" && liveAt === active)
      ? stream.shown
      : answerSize(answer.parts);
  const finished = !isLive;

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex items-center justify-between gap-2 border-b border-border px-3 py-2">
        <Button variant="ghost" size="sm" onClick={() => ask(QUESTION, "main")}>
          <PlusIcon aria-hidden="true" className="size-4" />
          New thread
        </Button>
        <Button variant="outline" size="sm" onClick={share}>
          <ShareIcon aria-hidden="true" className="size-4" />
          <span aria-live="polite">{shared ? "Link copied" : "Share"}</span>
        </Button>
      </header>

      <div className="mx-auto flex max-w-3xl flex-col gap-5 px-4 py-6 @md:px-8">
        <h2
          id={titleId}
          className="text-2xl font-semibold tracking-tight text-balance"
        >
          {question}
        </h2>
        <ThoughtRow
          thinking={thinking}
          seconds={answer.seconds}
          thought={answer.thought}
        />
        {thinking ? null : (
          <>
            <SourcesRow
              sources={SOURCES}
              lit={lit}
              onLight={setLit}
              open={sourcesOpen}
              onOpenChange={setSourcesOpen}
            />
            <section
              aria-label="Answer"
              aria-busy={isLive}
              className="flex gap-3"
            >
              {/* A box one text line tall centres the icon on the first line, with no nudge. */}
              <span className="flex h-5 shrink-0 items-center">
                <SparklesIcon
                  aria-hidden="true"
                  className="size-4 shrink-0 text-chart-2"
                />
              </span>
              <StreamAnswer
                className="min-w-0 flex-1 text-base"
                parts={answer.parts}
                shown={shown}
                live={isLive}
                litCite={lit}
                renderCite={(index) => {
                  const source = SOURCES[index - 1];
                  return source ? (
                    <CiteButton
                      index={index}
                      source={source}
                      lit={lit === index}
                      onLight={setLit}
                      onOpen={() => setSourcesOpen(true)}
                    />
                  ) : null;
                }}
              />
            </section>
          </>
        )}

        {finished ? (
          <ReplyActions
            className="border-y border-border py-1.5"
            text={answerText(answer.parts)}
            rating={version.rating}
            onRate={(rating) =>
              setVersions((list) =>
                list.map((item, index) =>
                  index === active ? { ...item, rating } : item,
                ),
              )
            }
            version={{
              index: active,
              count: versions.length,
              onPage: (delta) => setActive((index) => index + delta),
            }}
          >
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="ghost" size="sm" className="h-7">
                  <RefreshIcon aria-hidden="true" className="size-3.5" />
                  Regenerate
                  <ChevronDownIcon aria-hidden="true" className="size-3" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="start">
                {REGENERATE.map((option) => (
                  <DropdownMenuItem
                    key={option.id}
                    onSelect={() => regenerate(REGENERATE_TO[option.id])}
                  >
                    {option.label}
                  </DropdownMenuItem>
                ))}
              </DropdownMenuContent>
            </DropdownMenu>
          </ReplyActions>
        ) : (
          <Button
            variant="outline"
            size="sm"
            className="self-start"
            onClick={stream.stop}
          >
            Stop
          </Button>
        )}

        <section
          aria-labelledby={`${titleId}-related`}
          className="flex flex-col gap-1"
        >
          <h3 id={`${titleId}-related`} className="text-sm font-semibold">
            Related
          </h3>
          <ul className="flex flex-col gap-1">
            {RELATED.map((item) => (
              <li key={item.question}>
                <Button
                  variant="ghost"
                  className="h-auto w-full justify-between text-left whitespace-normal"
                  onClick={() => ask(item.question, item.answer)}
                >
                  {item.question}
                  <PlusIcon aria-hidden="true" className="size-4 shrink-0" />
                </Button>
              </li>
            ))}
          </ul>
        </section>

        <PromptField
          label="Ask a follow-up"
          placeholder="Ask a follow-up"
          busy={stream.busy}
          onSend={(text) => ask(text, "follow")}
          onStop={stream.stop}
        />
      </div>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";

import type { AnswerSource } from "./data";

/** Props for one numbered citation inside the answer. */
export interface CiteButtonProps {
  index: number;
  source: AnswerSource;
  lit: boolean;
  onLight: (index: number | null) => void;
  /** Opens the source cards, so the link lands on a visible card. */
  onOpen: () => void;
}

/**
 * A citation number. Hover or focus lights the sentence it supports and its
 * source card, and shows the source in a small tip.
 */
export function CiteButton({
  index,
  source,
  lit,
  onLight,
  onOpen,
}: CiteButtonProps) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <a
          href={`#source-${index}`}
          aria-label={`Source ${index}: ${source.title}`}
          onClick={onOpen}
          onMouseEnter={() => onLight(index)}
          onMouseLeave={() => onLight(null)}
          onFocus={() => onLight(index)}
          onBlur={() => onLight(null)}
          className={cn(
            "mx-0.5 inline-flex h-4 min-w-4 -translate-y-0.5 items-center justify-center rounded-full px-1 align-middle text-xs font-semibold tabular-nums no-underline outline-none focus-visible:ring-2 focus-visible:ring-ring",
            lit
              ? "bg-chart-2 text-background"
              : "bg-muted text-muted-foreground",
          )}
        >
          {index}
        </a>
      </TooltipTrigger>
      <TooltipContent className="max-w-64">
        <span className="block font-medium">{source.title}</span>
        <span className="block opacity-80">{source.site}</span>
      </TooltipContent>
    </Tooltip>
  );
}

import type { AnswerPart } from "../shared/answer";

/** One source an answer cites. */
export interface AnswerSource {
  title: string;
  site: string;
  /** The sentence the answer leans on. */
  excerpt: string;
  hue: string;
}

/** One answer the sample can show, with how long it thought. */
export interface SampleAnswer {
  seconds: number;
  thought: string;
  parts: AnswerPart[];
}

/** The sources every sample answer draws on. Sites are invented. */
export const SOURCES: AnswerSource[] = [
  {
    title: "Fernhill cancellation settings",
    site: "help.fernhill.app",
    excerpt:
      "A clinic sets its own cut-off, from 2 to 72 hours before the visit.",
