/** The opening question. */
export const QUESTION = "How should a small clinic handle late cancellations?";

/** Ways to regenerate an answer. */
export const REGENERATE = [
  { id: "shorter", label: "Shorter" },
  { id: "detail", label: "More detail" },
  { id: "simple", label: "Simpler words" },
] as const;

/** The id of one sample answer. */
export type AnswerId =
  "main" | "shorter" | "simple" | "fee" | "reminder" | "waitlist" | "follow";

/** The sample answers by id. */
export const ANSWERS = {
  main: {
