    parts: [
      {
        kind: "p",
        text: "Use a 24-hour cut-off with a $40 fee you mention at booking [3]. Waive it for illness [6], and offer each freed slot to the waitlist straight away [5].",
      },
    ],
  },
  simple: {
    seconds: 0.9,
    thought: "Plain words, no table.",
    parts: [
      {
        kind: "p",
        text: "Ask patients to cancel at least a day before [2]. Tell them about any fee when they book, so it is never a surprise [3].",
      },
