      },
    ],
  },
} satisfies Record<AnswerId, SampleAnswer>;

/** Related questions and the answer each one opens. */
export const RELATED: { question: string; answer: AnswerId }[] = [
  { question: "How much should a late cancellation fee be?", answer: "fee" },
  { question: "What should a reminder text say?", answer: "reminder" },
  { question: "How fast does a waitlist refill a slot?", answer: "waitlist" },
];

/** One block of a formatted reply. Inline `code` and citations like [2] live inside the text. */
export type AnswerPart =
  | { kind: "p"; text: string }
  | { kind: "h"; text: string }
  | { kind: "steps"; items: string[] }
  | { kind: "bullets"; items: string[] }
  | { kind: "code"; label: string; text: string }
  | { kind: "table"; head: string[]; rows: string[][] };

/** Splits a run of text into the words a stream reveals one group at a time. */
export const words = (text: string) => text.split(/\s+/).filter(Boolean);

/** How many stream steps one part takes: a word of text, a line of code or a row of a table. */
export function partSize(part: AnswerPart): number {
  switch (part.kind) {
    case "p":
    case "h":
      return words(part.text).length;
    case "steps":
    case "bullets":
      return part.items.reduce((sum, item) => sum + words(item).length, 0);
    case "code":
      return part.text.split("\n").length;
    case "table":
      return part.rows.length + 1;
  }
}

/** The number of stream steps a whole reply takes. */
export const answerSize = (parts: AnswerPart[]) =>
  parts.reduce((sum, part) => sum + partSize(part), 0);

/** The reply as plain text, for Copy. */
export function answerText(parts: AnswerPart[]): string {
  return parts
    .map((part) => {
      switch (part.kind) {
        case "p":
        case "h":
          return part.text;
        case "steps":
          return part.items
            .map((item, index) => `${index + 1}. ${item}`)
            .join("\n");
        case "bullets":
          return part.items.map((item) => `- ${item}`).join("\n");
        case "code":
          return part.text;
        case "table":
          return [part.head, ...part.rows]
            .map((row) => row.join(" | "))
            .join("\n");
      }
    })
    .join("\n\n")
    .replace(/`/g, "");
}

"use client";

import { useId } from "react";

import { ChevronDownIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import type { AnswerSource } from "./data";

/** Props for the row of source marks and the cards it opens. */
export interface SourcesRowProps {
  sources: AnswerSource[];
  lit: number | null;
  onLight: (index: number | null) => void;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

/**
 * A row of overlapping source marks with a count. Enter or Space opens the
 * sources as small cards; the card a citation points at lights with it.
 */
export function SourcesRow({
  sources,
  lit,
  onLight,
  open,
  onOpenChange,
}: SourcesRowProps) {
  const listId = useId();
  return (
    <div className="flex flex-col gap-2">
      <Button
        variant="outline"
