  const [open, setOpen] = useState(false);
  const panelId = useId();
  if (thinking) {
    return (
      <p
        className="flex items-center gap-1.5 text-sm text-muted-foreground"
        role="status"
      >
        <BulbIcon aria-hidden="true" className="size-4" />
        <span className="motion-safe:animate-pulse">Thinking</span>
      </p>
    );
  }
  return (
    <div className="flex flex-col gap-1">
      <Button
        variant="ghost"
        size="sm"
        className="-ml-2 self-start"
        aria-expanded={open}
        aria-controls={panelId}
        onClick={() => setOpen((value) => !value)}
      >
        <BulbIcon aria-hidden="true" className="size-4" />
        Thought for {seconds} s
        <ChevronRightIcon
          aria-hidden="true"
          className={cn(
            "size-3.5 motion-safe:transition-transform",
            open && "rotate-90",
          )}
        />
      </Button>
      <p
        id={panelId}
        hidden={!open}
        className="border-l-2 border-border pl-3 text-sm text-muted-foreground"
      >
        {thought}
      </p>
    </div>
  );
}
